CREATE TABLE people.consent_record (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    person_id uuid NOT NULL,
    given_by_person_id uuid NOT NULL,
    purpose varchar(30) NOT NULL,
    policy_version varchar(30) NOT NULL,
    granted_at timestamptz NOT NULL,
    withdrawn_at timestamptz,
    channel varchar(30) NOT NULL,
    recorded_by_user_id uuid,
    evidence_file_id uuid,
    ip_address inet,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    CONSTRAINT pk_consent_record PRIMARY KEY (id),
    CONSTRAINT ck_consent_record_purpose CHECK (purpose IN ('data_processing', 'photo_video_publication', 'public_profile', 'marketing', 'third_party_sharing', 'sms_whatsapp_messages', 'biometric_data')),
    CONSTRAINT ck_consent_record_channel CHECK (channel IN ('web', 'mobile_app', 'paper_form', 'email', 'in_person')),
    CONSTRAINT ck_consent_record_1 CHECK (withdrawn_at IS NULL OR withdrawn_at >= granted_at)
);
COMMENT ON TABLE people.consent_record IS 'Consent given (or withdrawn) for processing a person''s data for one purpose; for minors the consent is given by a guardian. Current consent = latest row per person and purpose with withdrawn_at NULL.';
COMMENT ON COLUMN people.consent_record.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
COMMENT ON COLUMN people.consent_record.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN people.consent_record.person_id IS 'Person the data belongs to.';
COMMENT ON COLUMN people.consent_record.given_by_person_id IS 'Person who gave the consent (the person, or a guardian for a minor).';
COMMENT ON COLUMN people.consent_record.purpose IS 'What the consent covers.';
COMMENT ON COLUMN people.consent_record.policy_version IS 'Version of the privacy notice / consent text shown.';
COMMENT ON COLUMN people.consent_record.granted_at IS 'When consent was given.';
COMMENT ON COLUMN people.consent_record.withdrawn_at IS 'When consent was withdrawn (NULL = in force).';
COMMENT ON COLUMN people.consent_record.channel IS 'How consent was captured.';
COMMENT ON COLUMN people.consent_record.recorded_by_user_id IS 'Staff who recorded a paper / in-person consent.';
COMMENT ON COLUMN people.consent_record.evidence_file_id IS 'Signed form or other evidence.';
COMMENT ON COLUMN people.consent_record.ip_address IS 'Client address for online consent.';
COMMENT ON COLUMN people.consent_record.created_at IS 'Row creation time.';
COMMENT ON COLUMN people.consent_record.created_by IS 'User account that created the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN people.consent_record.updated_at IS 'Last update time.';
COMMENT ON COLUMN people.consent_record.updated_by IS 'User account that last updated the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN people.consent_record.deleted_at IS 'Soft-delete marker; NULL = live row.';
COMMENT ON COLUMN people.consent_record.row_version IS 'Optimistic-locking version.';
CREATE UNIQUE INDEX ix_consent_record_1 ON people.consent_record (person_id, purpose) WHERE (withdrawn_at IS NULL AND deleted_at IS NULL);

